module string_match #(\n    parameter MAX_LEN = 16,\n    parameter DATA_WIDTH = 8\n) (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [DATA_WIDTH-1:0] s_arr [0:MAX_LEN-1],\n    input wire [DATA_WIDTH-1:0] t_arr [0:MAX_LEN-1],\n    input wire [4:0] n,\n    input wire [4:0] m,\n    output reg result,\n    output reg done\n);\n\n    // States\n    localparam [3:0] IDLE           = 4'd0;\n    localparam [3:0] FIND_STAR      = 4'd1;\n    localparam [3:0] CHECK_LENGTH   = 4'd2;\n    localparam [3:0] COMPARE_PREFIX = 4'd3;\n    localparam [3:0] COMPARE_SUFFIX = 4'd4;\n    localparam [3:0] DONE_ST        = 4'd5;\n\n    // State registers\n    reg [3:0] state, next_state;\n\n    // Working registers\n    reg [4:0] n_reg, m_reg;\n    reg has_star;\n    reg [3:0] pos_star;\n    reg [4:0] j;           // FIND_STAR counter\n    reg [4:0] i_prefix;    // COMPARE_PREFIX counter\n    reg [4:0] i_suffix;    // COMPARE_SUFFIX counter\n    reg prefix_match;\n    reg suffix_match;\n\n    // Combinational signals\n    wire [4:0] prefix_end = has_star ? ({1'b0, pos_star} + 5'd1) : n_reg;\n    wire [4:0] suffix_start = {1'b0, pos_star} + 5'd1;\n    wire [4:0] suffix_end = n_reg - 5'd1;\n    wire [4:0] t_offset = m_reg - n_reg;  // For COMPARE_SUFFIX t_arr index\n    wire [4:0] t_index = i_suffix + t_offset;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 1'b0;\n            has_star <= 1'b0;\n            pos_star <= 4'd0;\n            j <= 5'd0;\n            n_reg <= 5'd0;\n            m_reg <= 5'd0;\n            i_prefix <= 5'd0;\n            i_suffix <= 5'd0;\n            prefix_match <= 1'b0;\n            suffix_match <= 1'b0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        n_reg <= n;\n                        m_reg <= m;\n                        has_star <= 1'b0;\n                        pos_star <= 4'd0;\n                        j <= 5'd0;\n                        state <= FIND_STAR;\n                    end\n                end\n\n                FIND_STAR: begin\n                    if (j < n_reg) begin\n                        if (s_arr[j] == 8'd42 && !has_star) begin\n                            has_star <= 1'b1;\n                            pos_star <= j[3:0];\n                        end\n                        j <= j + 5'd1;\n                    end else begin\n                        state <= CHECK_LENGTH;\n                    end\n                end\n\n                CHECK_LENGTH: begin\n                    if (has_star) begin\n                        if (n_reg - 5'd1 <= m_reg) begin\n                            i_prefix <= 5'd0;\n                            prefix_match <= 1'b1;\n                            state <= COMPARE_PREFIX;\n                        end else begin\n                            result <= 1'b0;\n                            state <= DONE_ST;\n                        end\n                    end else begin\n                        if (n_reg == m_reg) begin\n                            i_prefix <= 5'd0;\n                            prefix_match <= 1'b1;\n                            state <= COMPARE_PREFIX;\n                        end else begin\n                            result <= 1'b0;\n                            state <= DONE_ST;\n                        end\n                    end\n                end\n\n                COMPARE_PREFIX: begin\n                    if (i_prefix < prefix_end) begin\n                        if (prefix_match && (s_arr[i_prefix] != t_arr[i_prefix])) begin\n                            prefix_match <= 1'b0;\n                        end\n                        i_prefix <= i_prefix + 5'd1;\n                    end else begin\n                        if (has_star) begin\n                            if (prefix_match) begin\n                                i_suffix <= suffix_start;\n                                suffix_match <= 1'b1;\n                                state <= COMPARE_SUFFIX;\n                            end else begin\n                                result <= 1'b0;\n                                state <= DONE_ST;\n                            end\n                        end else begin\n                            result <= prefix_match;\n                            state <= DONE_ST;\n                        end\n                    end\n                end\n\n                COMPARE_SUFFIX: begin\n                    if (i_suffix <= suffix_end) begin\n                        if (suffix_match && (s_arr[i_suffix] != t_arr[t_index[3:0]])) begin\n                            suffix_match <= 1'b0;\n                        end\n                        i_suffix <= i_suffix + 5'd1;\n                    end else begin\n                        result <= suffix_match;\n                        state <= DONE_ST;\n                    end\n                end\n\n                DONE_ST: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule